function table(headers,rows,footer=''){rows=rows.replace(/<tr>([\s\S]*?)<\/tr>/g,(_,cells)=>{let col=0;return '<tr>'+cells.replace(/<td\b([^>]*)>/g,(_,attrs)=>'<td data-label="'+esc(headers[col++])+'"'+attrs+'>')+'</tr>'});return `<div class="tablewrap"><table><thead><tr>${headers.map((h,i)=>`<th ${i===headers.length-1?'class="align-right"':''}>${h}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}">${empty('Không có dữ liệu','Thử thay đổi từ khóa hoặc bộ lọc.')}</td></tr>`}</tbody></table></div>${footer?`<div class="tablefoot">${footer}</div>`:''}`}
const empty=(title,desc,action='')=>`<div class="empty">${icon('search')}<h3>${title}</h3><p>${desc}</p>${action}</div>`;
const metric=value=>/^\d[\d.]*$/.test(String(value))?`<span data-count="${String(value).replaceAll('.','')}" data-final="${value}" aria-label="${value}">${value}</span>`:esc(value);
const stat=(title,value,unit,description,ic,featured=false)=>`<article class="card stat ${featured?'featured':''}"><div class="label">${title}${icon(ic)}</div><div class="value number">${metric(value)}<small>${unit}</small></div><div class="note">${description}</div></article>`;
function chart(rows,start,end){let days=[],d=new Date(start+'T12:00:00+07:00');let count=0;while(d.toISOString().slice(0,10)<=end&&count<92){const day=d.toISOString().slice(0,10);days.push({day,total:sum(rows.filter(i=>i.date===day))});d.setUTCDate(d.getUTCDate()+1);count++}const max=Math.max(100000,...days.map(d=>d.total));if(days.length>14)return `<div class="tablewrap" style="max-height:240px">${table(['Ngày','Doanh thu'],days.map(d=>`<tr><td>${dateFormat(d.day)}</td><td class="align-right">${money(d.total)}</td></tr>`).join(''))}</div>`;return `<div class="chart" role="img" aria-label="Doanh thu từng ngày từ ${dateFormat(start)} đến ${dateFormat(end)}"><div class="axis"><span>${(max/1000000).toFixed(1)}tr</span><span>${(max*.66/1000000).toFixed(1)}tr</span><span>${(max*.33/1000000).toFixed(1)}tr</span><span>0</span></div>${days.map(d=>`<div class="barcol"><div class="bar ${d.day===today?'current':''}" style="--height:${d.total/max*88}%"><span class="barvalue">${d.total?(d.total>=1000000?(d.total/1000000).toLocaleString('vi-VN',{maximumFractionDigits:1})+'tr':(d.total/1000).toLocaleString('vi-VN',{maximumFractionDigits:1})+'k'):'0'}</span></div><span class="day">${d.day.slice(8)}/${d.day.slice(5,7)}</span></div>`).join('')}</div>`}
function topProducts(rows){const map={};rows.forEach(i=>i.items.forEach(it=>{if(!map[it.id])map[it.id]={id:it.id,name:it.name,qty:0,total:0};map[it.id].qty+=it.qty;map[it.id].total+=it.price*it.qty-Math.round(it.price*it.qty*it.percent/100)}));return Object.values(map).sort((a,b)=>b.qty-a.qty||a.id.localeCompare(b.id))}
function invoiceRows(rows){return rows.map(i=>`<tr><td><button class="cell-link" data-invoice="${i.id}">${i.id}</button></td><td>${i.name}<span class="muted small" style="display:block">${i.register}</span></td><td>${dateFormat(i.date)}<span class="muted small" style="display:block">${i.time}</span></td><td>${badge('Đã thanh toán','success')}</td><td class="align-right number">${money(i.total)}</td></tr>`).join('')}
function shiftCard(){const s=currentShift(),rows=s?invoices.filter(i=>i.shift===s.id):[];return `<article class="card"><div class="cardhead"><div><h2>Ca làm việc hiện tại</h2><p>Thông tin tại quầy bán hàng</p></div>${badge(s?'Đang mở':'Chưa mở ca',s?'success':'neutral')}</div>${s?`<div class="shift-surface"><div class="shift-name"><span class="avatar">MA</span><div><strong>${esc(s.name)}</strong><p>${s.register} · ${s.id}</p></div></div><div class="shift-time"><div><p class="muted small">Mở ca lúc</p><span class="number">${s.start}</span></div><div style="text-align:right"><p class="muted small">Ngày làm việc</p><span class="number" style="font-size:13px">${dateFormat(s.date)}</span></div></div></div><div class="kv"><span>Tiền đầu ca</span><span>${money(s.opening)}</span></div><div class="kv"><span>Hóa đơn hoàn tất</span><span>${rows.length} hóa đơn</span></div><div class="kv"><span>Doanh thu tiền mặt</span><span>${money(sum(rows))}</span></div><div class="shift-buttons">${btn('Chi tiết ca','my-shift','','clock')}${state.role==='cashier'?btn('Tiếp tục bán','go-pos','primary','pos'):btn('Xem các ca','go-shifts','primary','arrow')}</div>`:empty('Sẵn sàng cho ca mới','Mở ca và nhập tiền đầu ca trước khi bắt đầu bán hàng.',state.role==='cashier'?btn('Mở ca','open-shift','primary','plus'):btn('Xem các ca','go-shifts','primary'))}</article>`}
function dashboard(){const day=invoices.filter(i=>i.date===today),week=inRange(invoices,'2026-10-29',today),best=topProducts(week);return pagehead('Tổng quan vận hành','Chào buổi sáng, Nguyễn Lan. Cùng theo dõi nhịp bán hàng hôm nay.','<span class="btn">'+icon('calendar')+'04 tháng 11, 2026</span>'+btn('Xem báo cáo','go-reports','primary','chart'),'BẢNG ĐIỀU KHIỂN · QUẢN LÝ')+`<div class="stats">${stat('Doanh thu hôm nay',money(sum(day)).replace(' ₫',''),'₫','Sau khuyến mãi · Thanh toán thành công','wallet',true)}${stat('Hóa đơn hoàn tất',day.length,'hóa đơn','Chỉ tính hóa đơn đã phát hành','receipt')}${stat('Giá trị trung bình',money(day.length?sum(day)/day.length:0).replace(' ₫',''),'₫','Doanh thu / số hóa đơn','chart')}${stat('Quầy đang hoạt động',shifts.filter(s=>s.status==='open').length,'quầy','Các ca đang mở trong hệ thống','pos')}</div><div class="grid-main"><div class="stack"><article class="card"><div class="cardhead"><div><h2>Doanh thu 7 ngày gần nhất</h2><p>Từ 29/10 đến 04/11/2026</p></div><div class="chart-tabs"><span class="selected">7 ngày</span></div></div><div class="chart-summary"><span class="big number">${money(sum(week))}</span><span class="badge">${week.length} hóa đơn</span></div>${chart(week,'2026-10-29',today)}<div class="chartfoot"><span class="legend"><i class="dot"></i>Doanh thu sau giảm giá</span><button class="link" data-action="go-reports">Xem chi tiết ${icon('arrow')}</button></div></article><article class="card table-card"><div class="cardhead"><div><h2>Hóa đơn gần đây</h2><p>Thông tin được lưu tại thời điểm bán</p></div><button class="link" data-action="go-invoices">Tất cả hóa đơn ${icon('arrow')}</button></div>${table(['Mã hóa đơn','Thu ngân','Thời gian','Trạng thái','Tổng tiền'],invoiceRows([...invoices].reverse().slice(0,4)),`<span>4 hóa đơn mới nhất</span><span>Thanh toán tiền mặt</span>`)}</article></div><div class="stack">${shiftCard()}<article class="card"><div class="cardhead"><div><h2>Sản phẩm bán nhiều</h2><p>Theo số lượng · 7 ngày gần nhất</p></div><span class="icon-tile">${icon('box')}</span></div><div class="product-list">${best.slice(0,3).map(p=>`<div class="product-row">${art(products.find(x=>x.id===p.id),true)}<div class="info"><strong>${p.name}</strong><p>${p.id}</p></div><div class="sold">${p.qty}<small>${money(p.total)}</small></div></div>`).join('')}</div><button class="link" data-action="go-reports" style="margin-top:14px">Xem thống kê sản phẩm ${icon('arrow')}</button></article><article class="card"><div class="cardhead" style="margin-bottom:5px"><h2>Cần chú ý</h2><span class="badge warning">Tồn thấp</span></div>${products.filter(p=>p.active&&p.stock<10).map(p=>`<div class="stocknotice">${icon('alert')}<div><p>${p.name}</p><small>Còn ${p.stock} ${p.unit.toLowerCase()}</small></div></div>`).join('')}<button class="link" data-action="go-products">Kiểm tra sản phẩm ${icon('arrow')}</button></article></div></div>`}
function pos(){const s=currentShift();if(!s)return pagehead('Bán hàng tại quầy','Mở ca để bắt đầu giao dịch với khách hàng.')+`<article class="card">${empty('Bạn chưa có ca đang mở','Mỗi thu ngân chỉ có một ca đang mở. Mọi hóa đơn sẽ được gắn với thu ngân và quầy của ca.',btn('Mở ca bán hàng','open-shift','primary','plus'))}</article>`;
 const visible=products.filter(p=>(state.category==='Tất cả'||p.category===state.category)&&matches(p.name+' '+p.barcode+' '+p.id,state.search));const totals=cartTotals();
 return pagehead('Bán hàng',`${s.register} · ${esc(s.name)} · Mở ca ${s.start}`,badge('Ca đang mở','success')+btn('Xem ca','my-shift','','clock'),'QUẦY THU NGÂN')+`<div class="pos-layout"><div class="pos-catalog"><form id="scan-form" class="scan"><div class="scanner-label"><span>Quét mã sản phẩm</span><kbd>F2</kbd></div>${icon('scan')}<div class="field"><input id="barcode" aria-label="Quét hoặc nhập mã vạch" placeholder="Quét hoặc nhập mã vạch sản phẩm" autocomplete="off"></div><button class="btn primary" type="submit">Thêm</button></form><div class="filters">${searchBox('Tìm sản phẩm theo tên hoặc mã…',state.search)}</div><div class="category-tabs">${['Tất cả',...new Set(products.map(p=>p.category))].map(c=>`<button class="chip ${state.category===c?'active':''}" data-category="${c}">${c}</button>`).join('')}</div><div class="product-grid">${visible.map(p=>`<button class="product-card" data-add="${p.id}" ${!p.active||p.stock===0?'disabled':''}>${art(p)}${discountFor(p.id)?`<span class="badge">−${discountFor(p.id)}%</span>`:''}<h3>${p.name}</h3><p class="muted small">${p.id} · ${p.active?'Còn '+p.stock+' '+p.unit.toLowerCase():'Ngừng bán'}</p><div class="between" style="align-items:flex-end;margin-top:auto"><div class="price number">${money(p.price*(1-discountFor(p.id)/100))}${discountFor(p.id)?`<span class="old">${money(p.price)}</span>`:''}</div><span class="plus">${icon('plus')}</span></div></button>`).join('')||empty('Không tìm thấy sản phẩm','Thử tìm bằng tên, mã sản phẩm hoặc mã vạch.')}</div></div><article class="card cart"><div class="cart-top"><div class="between"><h2>Đơn bán hàng</h2><span class="badge neutral">Đang lập</span></div><p class="muted small" style="margin-top:5px">Khách lẻ · ${s.register}</p></div><div class="cart-items">${state.cart.length?state.cart.map(i=>cartLine(i)).join(''):empty('Giỏ hàng đang trống','Quét mã vạch hoặc chọn sản phẩm ở bên trái.')}</div><div class="cart-summary"><div class="kv"><span>Số lượng sản phẩm</span><span>${state.cart.reduce((s,i)=>s+i.qty,0)}</span></div><div class="kv"><span>Tạm tính</span><span>${money(totals.sub)}</span></div><div class="kv"><span>Giảm khuyến mãi</span><span>−${money(totals.discount)}</span></div><div class="kv total"><span>Khách cần trả</span><span class="number">${money(totals.total)}</span></div></div>${note('Khuyến mãi có hiệu lực được áp dụng tự động.','', 'tag')}<div class="cart-bottom">${btn('Hủy đơn','cancel-order','','trash')}<button class="btn primary" data-action="checkout" ${!state.cart.length?'disabled':''}>${icon('wallet')}Thanh toán<kbd>F4</kbd></button></div></article></div>`}
function cartLine(i){const p=products.find(p=>p.id===i.id),percent=discountFor(p.id),amount=p.price*i.qty-Math.round(p.price*i.qty*percent/100);return `<div class="cart-line" data-cart-line="${p.id}">${art(p,true)}<div class="info"><div class="name">${p.name}</div><div class="price">${money(p.price)} / ${p.unit.toLowerCase()} ${percent?`<span class="badge">−${percent}%</span>`:''}</div><div class="quantity"><button data-qty="${i.id}" data-delta="-1" aria-label="Giảm ${p.name}">−</button><input type="number" min="1" max="${p.stock}" value="${i.qty}" data-quantity="${i.id}" aria-label="Số lượng ${p.name}"><button data-qty="${i.id}" data-delta="1" aria-label="Tăng ${p.name}">+</button></div></div><div class="amount number">${money(amount)}<button class="remove" data-remove="${i.id}" aria-label="Xóa ${p.name}">${icon('trash')}</button></div></div>`}
function matches(text,q){const normalize=x=>x.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d');return normalize(text).includes(normalize(q||''))}
function productPage(){const visible=products.filter(p=>matches(p.name+' '+p.id+' '+p.barcode,state.search)&&(state.productStatus==='all'||String(p.active)===state.productStatus));return pagehead('Quản lý sản phẩm','Thông tin sản phẩm, giá bán và số lượng hiện có tại siêu thị.',btn('Thêm sản phẩm','new-product','primary','plus'),'DANH MỤC & GIÁ BÁN')+`<div class="stats">${stat('Tất cả sản phẩm',products.length,'sản phẩm','Danh mục hàng hóa của siêu thị','box')}${stat('Đang bán',products.filter(p=>p.active).length,'sản phẩm','Có thể thêm vào đơn hàng','check')}${stat('Ngừng bán',products.filter(p=>!p.active).length,'sản phẩm','Giữ nguyên lịch sử bán hàng','lock')}${stat('Sắp hết hàng',products.filter(p=>p.active&&p.stock<10).length,'sản phẩm','Tồn hiện tại dưới 10 đơn vị','alert')}</div><div class="filters">${searchBox('Tìm tên, mã sản phẩm hoặc mã vạch…',state.search)}<div class="field"><label for="product-status">Trạng thái bán</label>${select('product-status',[['all','Tất cả trạng thái'],['true','Đang bán'],['false','Ngừng bán']],state.productStatus)}</div></div><article class="card table-card">${table(['Sản phẩm','Mã vạch','Loại hàng','Giá bán','Tồn kho','Trạng thái','Thao tác'],visible.map(p=>`<tr><td><div class="table-name">${art(p,true)}<div>${esc(p.name)}<span class="sub">${p.id} · ${p.unit}</span></div></div></td><td class="muted">${p.barcode}</td><td>${esc(p.category)}</td><td class="number">${money(p.price)}</td><td>${p.stock} ${p.stock<10&&p.active?'<span class="badge warning">Tồn thấp</span>':''}</td><td>${badge(p.active?'Đang bán':'Ngừng bán',p.active?'success':'neutral')}</td><td class="align-right"><button class="iconbtn" data-edit-product="${p.id}" aria-label="Sửa ${esc(p.name)}">${icon('edit')}</button><button class="cell-link" data-toggle-product="${p.id}">${p.active?'Ngừng bán':'Kích hoạt'}</button>${!p.active?`<button class="iconbtn" data-delete-product="${p.id}" aria-label="Xóa ${esc(p.name)}">${icon('trash')}</button>`:''}</td></tr>`).join(''),`<span>${visible.length} sản phẩm</span><span>Trang 1 / 1</span>`)}</article>`}
function promotionPage(){const rows=promos.filter(p=>matches(products.find(x=>x.id===p.product)?.name+' '+p.id,state.search)&&(state.promoStatus==='all'||promoState(p)===state.promoStatus));return pagehead('Khuyến mãi','Một mức giảm phù hợp, đúng sản phẩm, đúng thời điểm.',btn('Tạo khuyến mãi','new-promo','primary','plus'),'CHƯƠNG TRÌNH ƯU ĐÃI')+`<div class="stats">${stat('Đang áp dụng',promos.filter(p=>promoState(p)==='Đang áp dụng').length,'chương trình','Tự động giảm giá tại quầy','tag',true)}${stat('Sắp diễn ra',promos.filter(p=>promoState(p)==='Sắp diễn ra').length,'chương trình','Đã lên lịch, chưa áp dụng','calendar')}${stat('Đã kết thúc',promos.filter(p=>promoState(p)==='Đã kết thúc').length,'chương trình','Giữ để tra cứu lịch sử','clock')}${stat('Kiểu ưu đãi','Theo %','','Giảm giá theo từng sản phẩm','box')}</div><div class="filters">${searchBox('Tìm mã hoặc sản phẩm khuyến mãi…',state.search)}<div class="field"><label for="promo-status">Trạng thái</label>${select('promo-status',['Tất cả','Đang áp dụng','Sắp diễn ra','Đã kết thúc','Đã hủy'].map((t,i)=>[i?t:'all',t]),state.promoStatus)}</div></div><article class="card table-card">${table(['Sản phẩm áp dụng','Mức giảm','Bắt đầu','Kết thúc','Trạng thái','Thao tác'],rows.map(p=>{const product=products.find(x=>x.id===p.product),status=promoState(p);return `<tr><td><div class="table-name">${art(product,true)}<div>${esc(product.name)}<span class="sub">${p.id} · ${p.product}</span></div></div></td><td><span class="badge">−${p.percent}%</span></td><td>${dateFormat(p.start)}</td><td>${dateFormat(p.end)}</td><td>${badge(status,status==='Đang áp dụng'?'success':status==='Sắp diễn ra'?'warning':'neutral')}</td><td class="align-right">${status==='Sắp diễn ra'?`<button class="cell-link" data-edit-promo="${p.id}">Chỉnh sửa</button>`:''}${['Sắp diễn ra','Đang áp dụng'].includes(status)?`<button class="btn ghost" data-cancel-promo="${p.id}">Hủy</button>`:`<button class="cell-link" data-view-promo="${p.id}">Xem chi tiết</button>`}</td></tr>`}).join(''),`<span>${rows.length} chương trình</span><span>Ngày đối chiếu: ${dateFormat(today)}</span>`)}</article><div style="margin-top:20px">${note('Không áp dụng đồng thời hai chương trình cho cùng sản phẩm trong khoảng thời gian giao nhau. Hóa đơn đã phát hành luôn giữ nguyên giá và số tiền giảm.')}</div>`}
function invoicesPage(source=false){const rows=inRange(myInvoices(),state.invoiceStart,state.invoiceEnd).filter(i=>matches(i.id+' '+i.name,state.search)).sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time));return pagehead(source?'Hóa đơn nguồn báo cáo':'Tra cứu hóa đơn',source?'Danh sách sử dụng cùng khoảng thời gian với báo cáo doanh thu.':'Tra cứu giao dịch hoàn tất, xem chi tiết và in lại hóa đơn.',source?btn('Về báo cáo','go-reports','','chart'):'','HÓA ĐƠN BÁN HÀNG')+`<div class="filters">${searchBox('Tìm mã hóa đơn hoặc thu ngân…',state.search)}<div class="field"><label for="invoice-start">Từ ngày</label><input id="invoice-start" type="date" value="${state.invoiceStart}" max="9999-12-31"></div><div class="field"><label for="invoice-end">Đến ngày</label><input id="invoice-end" type="date" value="${state.invoiceEnd}" max="9999-12-31"></div></div>${state.invoiceStart&&state.invoiceEnd&&state.invoiceStart>state.invoiceEnd?note('Ngày kết thúc phải bằng hoặc sau ngày bắt đầu.','danger'):''}<article class="card table-card"><div class="cardhead"><div><h2>Hóa đơn đã thanh toán</h2><p>${rows.length} hóa đơn trong điều kiện đã chọn</p></div><span class="badge">Tiền mặt</span></div>${table(['Mã hóa đơn','Thu ngân','Thời gian','Trạng thái','Tổng thanh toán'],invoiceRows(rows),`<span>Tổng ${rows.length} hóa đơn</span><span class="number">Tổng thanh toán: ${money(sum(rows))}</span>`)}</article>`}
const cancelledOrders=[{id:'BH-1104-008',date:today,time:'09:35',name:'Trần Minh Anh',reason:'Khách đổi ý, không mua hàng',total:64000}];
function ordersPage(){const data=myInvoices().map(i=>({...i,kind:'paid'})).concat(cancelledOrders.filter(i=>state.role!=='cashier'||i.name===cashierName()).map(i=>({...i,kind:'cancelled'}))).sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time)).filter(i=>matches((i.order||i.id)+' '+i.name,state.search)&&(state.orderStatus==='all'||state.orderStatus===i.kind));return pagehead('Đơn hàng','Theo dõi đơn đã thanh toán và lịch sử đơn bị hủy.',state.role==='cashier'?btn('Tạo đơn mới','go-pos','primary','plus'):'','LỊCH SỬ GIAO DỊCH')+`<div class="filters">${searchBox('Tìm mã đơn hoặc thu ngân…',state.search)}<div class="field"><label for="order-status">Trạng thái</label>${select('order-status',[['all','Tất cả trạng thái'],['paid','Đã thanh toán'],['cancelled','Đã hủy']],state.orderStatus)}</div></div><article class="card table-card">${table(['Mã đơn hàng','Thu ngân','Thời gian','Trạng thái','Giá trị','Thao tác'],data.map(i=>`<tr><td>${i.order||i.id}</td><td>${i.name}</td><td>${dateFormat(i.date)} · ${i.time}</td><td>${badge(i.kind==='paid'?'Đã thanh toán':'Đã hủy',i.kind==='paid'?'success':'neutral')}</td><td class="number">${money(i.total)}</td><td class="align-right">${i.kind==='paid'?`<button class="cell-link" data-invoice="${i.id}">Xem hóa đơn</button>`:`<button class="cell-link" data-cancel-detail="${i.id}">Lý do hủy</button>`}</td></tr>`).join(''),`<span>${data.length} đơn hàng</span><span>Đơn đã thanh toán không được sửa hoặc hủy</span>`)}</article>`}
function shiftsPage(){if(state.role==='cashier'){const s=currentShift(),rows=s?invoices.filter(i=>i.shift===s.id):[];return pagehead('Ca làm việc của tôi','Quản lý tiền đầu ca, theo dõi giao dịch và đối soát khi kết thúc.',s?btn('Kết thúc ca','close-shift','','lock'):btn('Mở ca mới','open-shift','primary','plus'),'THU NGÂN · '+esc(cashierName()).toUpperCase())+`<div class="two-col"><div class="stack"><div class="stats" style="grid-template-columns:1fr 1fr">${stat('Doanh thu của ca',money(sum(rows)).replace(' ₫',''),'₫','Chỉ tính hóa đơn thuộc ca hiện tại','wallet',true)}${stat('Hóa đơn hoàn tất',rows.length,'hóa đơn','Không bao gồm đơn hủy','receipt')}</div><article class="card table-card"><div class="cardhead"><div><h2>Hóa đơn trong ca</h2><p>${s?s.id:'Chưa có ca đang mở'}</p></div></div>${table(['Mã hóa đơn','Thu ngân','Thời gian','Trạng thái','Tổng tiền'],invoiceRows(rows))}</article></div>${shiftCard()}</div>`}
 const rows=shifts.filter(s=>(state.shiftStatus==='all'||s.status===state.shiftStatus)&&(state.shiftCashier==='all'||s.name===state.shiftCashier)&&(state.shiftRegister==='all'||s.register===state.shiftRegister)&&(!state.shiftStart||s.date>=state.shiftStart)&&(!state.shiftEnd||s.date<=state.shiftEnd));return pagehead('Ca làm việc','Theo dõi thu ngân, quầy bán hàng và số liệu đối soát của từng ca.','','VẬN HÀNH & ĐỐI SOÁT')+`<div class="filters"><div class="field"><label for="shift-start">Từ ngày</label><input id="shift-start" type="date" value="${state.shiftStart}"></div><div class="field"><label for="shift-end">Đến ngày</label><input id="shift-end" type="date" value="${state.shiftEnd}"></div><div class="field"><label for="shift-cashier">Thu ngân</label>${select('shift-cashier',[['all','Tất cả thu ngân'],...['Trần Minh Anh','Lê Thanh Bình'].map(n=>[n,n])],state.shiftCashier)}</div><div class="field"><label for="shift-register">Quầy</label>${select('shift-register',[['all','Tất cả quầy'],['Quầy 01','Quầy 01'],['Quầy 02','Quầy 02']],state.shiftRegister)}</div><div class="field"><label for="shift-status">Trạng thái</label>${select('shift-status',[['all','Tất cả trạng thái'],['open','Đang mở'],['closed','Đã kết thúc']],state.shiftStatus)}</div></div>${state.shiftStart&&state.shiftEnd&&state.shiftStart>state.shiftEnd?note('Khoảng ngày không hợp lệ. Vui lòng chọn lại.','danger'):''}<article class="card table-card">${table(['Mã ca / Quầy','Thu ngân','Thời gian','Doanh thu','Trạng thái','Thao tác'],rows.map(s=>`<tr><td>${s.id}<span class="muted small" style="display:block">${s.register}</span></td><td>${s.name}</td><td>${dateFormat(s.date)}<span class="muted small" style="display:block">${s.start} – ${s.end||'Đang mở'}</span></td><td class="number">${money(sum(invoices.filter(i=>i.shift===s.id)))}</td><td>${badge(s.status==='open'?'Đang mở':'Đã kết thúc',s.status==='open'?'success':'neutral')}</td><td class="align-right"><button class="cell-link" data-shift="${s.id}">Xem chi tiết</button></td></tr>`).join(''),`<span>${rows.length} ca làm việc</span><span>Lọc theo thời gian, thu ngân, quầy và trạng thái</span>`)}</article>`}
function reportPage(){const start=state.reportStart,end=state.reportEnd,valid=!!start&&!!end&&start<=end,days=valid?(new Date(end)-new Date(start))/86400000+1:0;const rows=valid?inRange(invoices,start,end):[],total=sum(rows),top=topProducts(rows);return pagehead('Báo cáo doanh thu','Nhìn rõ kết quả kinh doanh từ những hóa đơn đã hoàn tất.',btn('Đối chiếu hóa đơn','source-invoices','','receipt'),'PHÂN TÍCH BÁN HÀNG')+`<article class="card" style="margin-bottom:20px"><form id="report-form" class="filters report-filters" style="margin:0"><div class="field"><label for="report-start">Từ ngày</label><input id="report-start" type="date" value="${start}" required></div><div class="field"><label for="report-end">Đến ngày</label><input id="report-end" type="date" value="${end}" required></div><button class="btn primary" type="submit">${icon('calendar')}Áp dụng</button><button class="btn ghost" data-action="report-today" type="button">Hôm nay</button><button class="btn ghost" data-action="report-week" type="button">7 ngày gần nhất</button><span class="muted small" style="margin-left:auto;align-self:center">Giờ Việt Nam · Bao gồm cả hai ngày</span></form></article>${!valid?note('Vui lòng chọn đủ ngày; ngày kết thúc phải bằng hoặc sau ngày bắt đầu.','danger'):''}${days>92?note('Demo hỗ trợ tối đa 92 ngày mỗi lần xem. Vui lòng thu hẹp khoảng ngày.','warning'):''}<div class="stats report-stats">${stat('Tổng doanh thu',money(total).replace(' ₫',''),'₫','Tổng tiền sau giảm giá của hóa đơn hoàn tất','wallet',true)}${stat('Số hóa đơn',rows.length,'hóa đơn','Mỗi hóa đơn được đếm một lần','receipt')}${stat('Giá trị trung bình',money(rows.length?total/rows.length:0).replace(' ₫',''),'₫','Doanh thu / số hóa đơn','chart')}</div><div class="equal-cols"><article class="card"><div class="cardhead"><div><h2>Doanh thu theo ngày</h2><p>${valid?dateFormat(start)+' – '+dateFormat(end):'Chưa có khoảng ngày hợp lệ'}</p></div><span class="icon-tile">${icon('chart')}</span></div>${valid&&days<=92?chart(rows,start,end):empty('Chưa thể hiển thị biểu đồ','Chọn khoảng ngày hợp lệ, tối đa 92 ngày.')}<div class="chartfoot"><span class="legend"><i class="dot"></i>Ngày không phát sinh: 0 ₫</span><span>Tổng ${money(total)}</span></div></article><article class="card table-card"><div class="cardhead"><div><h2>Sản phẩm bán nhiều</h2><p>Xếp theo tổng số lượng bán giảm dần</p></div></div>${table(['Sản phẩm','Số lượng','Doanh thu sau giảm'],top.map((p,j)=>`<tr><td><div class="table-name"><span class="muted small">${String(j+1).padStart(2,'0')}</span><div>${esc(p.name)}<span class="sub">${p.id}</span></div></div></td><td>${p.qty}</td><td class="align-right number">${money(p.total)}</td></tr>`).join(''))}</article></div><div style="margin-top:20px">${note('Doanh thu cộng từ hóa đơn bán thành công sau giảm giá; không cộng tiền đầu ca, tiền khách đưa hoặc tiền thừa. Trả / đổi được trình bày riêng, chưa tính vào báo cáo này.')}</div>`}
function accountsPage(){const rows=accounts.filter(a=>matches(a.name+' '+a.username,state.search)&&(state.accountRole==='all'||state.accountRole===a.role));return pagehead('Quản lý tài khoản','Cấp tài khoản, gán vai trò và kiểm soát quyền đăng nhập của nhân viên.',btn('Tạo tài khoản','new-account','primary','plus'),'KHÔNG GIAN QUẢN TRỊ')+`<div class="filters">${searchBox('Tìm họ tên hoặc tên đăng nhập…',state.search)}<div class="field"><label for="account-role">Vai trò</label>${select('account-role',[['all','Tất cả vai trò'],...Object.entries(roleNames)],state.accountRole)}</div></div><article class="card table-card">${table(['Nhân viên','Tên đăng nhập','Vai trò','Trạng thái','Thao tác'],rows.map(a=>`<tr><td><div class="table-name"><span class="avatar">${a.name.split(' ').slice(-2).map(n=>n[0]).join('')}</span>${esc(a.name)}</div></td><td>${esc(a.username)}</td><td>${roleNames[a.role]}</td><td>${badge(a.active?'Hoạt động':'Đã khóa',a.active?'success':'neutral')}</td><td class="align-right">${a.active?`<button class="cell-link" data-lock-account="${a.id}" ${a.username===state.username?'disabled title="Tài khoản đang sử dụng"':''}>${icon('lock')} Khóa tài khoản</button>`:'<span class="muted small">Không thể đăng nhập</span>'}</td></tr>`).join(''),`<span>${rows.length} tài khoản · ${rows.filter(a=>!a.active).length} bị khóa</span><span>Khóa tài khoản không xóa lịch sử</span>`)}</article><div style="margin-top:20px">${note('Tài khoản mới phải có vai trò và tên đăng nhập duy nhất. Chỉ quản trị viên được tạo hoặc khóa tài khoản. Dữ liệu ở đây là dữ liệu demo trên trình duyệt.','', 'shield')}</div>`}
function permissionsPage(){const matrix=[['Bán hàng, thanh toán tiền mặt',1,0,0],['Xem hóa đơn',1,1,0],['Mở và kết thúc ca của mình',1,0,0],['Xem lịch sử tất cả ca',0,1,0],['Quản lý sản phẩm, khuyến mãi',0,1,0],['Xem báo cáo, hóa đơn nguồn',0,1,0],['Đề nghị trả / đổi hàng',1,1,0],['Xác nhận đề nghị trả / đổi',0,1,0],['Tạo và khóa tài khoản',0,0,1]];return pagehead('Phân quyền theo vai trò','Tham chiếu các quyền sử dụng theo nhóm người dùng trong tài liệu.','','QUẢN TRỊ TRUY CẬP')+`<article class="card table-card"><div class="cardhead"><div><h2>Ma trận chức năng</h2><p>Ba vai trò: Thu ngân, Quản lý và Quản trị viên</p></div><span class="icon-tile">${icon('shield')}</span></div>${table(['Chức năng','Thu ngân','Quản lý','Quản trị viên'],matrix.map(r=>`<tr><td>${r[0]}</td>${r.slice(1).map(x=>`<td style="text-align:center">${x?`<span style="color:var(--success)">${icon('check')} Được phép</span>`:'<span class="muted">—</span>'}</td>`).join('')}</tr>`).join(''))}</article><div style="margin-top:20px">${note('Bản demo chỉ mô phỏng việc hiển thị theo vai trò. Khi tích hợp Spring Security, quyền phải được kiểm tra ở máy chủ cho từng yêu cầu; ẩn menu không thay thế xác thực và phân quyền.','', 'shield')}</div>`}
function returnsPage(){return pagehead('Trả / đổi hàng theo hóa đơn','Tra cứu hóa đơn gốc, chọn hàng cần xử lý và gửi quản lý xác nhận.','','HỖ TRỢ SAU BÁN HÀNG')+`<div class="two-col"><div class="stack"><article class="card"><div class="cardhead"><div><h2>1. Tra cứu hóa đơn gốc</h2><p>Chỉ sử dụng hóa đơn đã thanh toán</p></div></div><form id="return-search" class="row"><div class="field" style="flex:1"><label for="return-invoice">Mã hóa đơn hoặc mã vạch</label><input id="return-invoice" value="${invoices.at(-1).id}" placeholder="Nhập số hóa đơn"></div><button class="btn primary" style="align-self:flex-end" type="submit">${icon('search')}Tra cứu</button></form></article><div id="return-result">${empty('Chọn hóa đơn cần xử lý','Thông tin và số lượng đã mua sẽ xuất hiện sau khi tra cứu.')}</div></div><article class="card"><div class="cardhead"><div><h2>Quy trình xác nhận</h2><p>Thao tác thuộc kế hoạch Sprint 3</p></div><span class="icon-tile">${icon('return')}</span></div><div class="timeline"><div><p>Tra cứu hóa đơn đã bán</p><small>Dùng thông tin và giá đã lưu</small></div><div><p>Chọn sản phẩm và số lượng</p><small>Không vượt quá số lượng đã mua</small></div><div><p>Quản lý xác nhận</p><small>Trước khi hoàn tiền hoặc cập nhật tồn</small></div></div>${note('Màn này minh họa đề nghị và phê duyệt. Chưa ghi hoàn tiền, thay đổi tồn kho hoặc doanh thu.','warning')}</article></div>`}
let lastRenderKey='';
function render(){closeOpenSelect(true);if(!state.loggedIn)return renderLogin();if(!allowed[state.role].includes(state.page))state.page=allowed[state.role][0];const renderKey=state.role+state.username+state.page,entering=lastRenderKey!==renderKey;lastRenderKey=renderKey;document.body?.classList.remove('navigation-open');const page=nav.find(n=>n[0]===state.page),name=principal().name;const groups=[['overview','KHÔNG GIAN CHUNG'],['operations','NGHIỆP VỤ TẠI QUẦY'],['management','QUẢN LÝ'],['system','HỆ THỐNG']];
 document.getElementById('root').innerHTML=`<div class="frame ${state.role==='cashier'?'cashier-shell':''} ${state.page==='pos'?'selling':''}"><aside class="sidebar" id="sidebar"><a class="brand pos-brand" href="#${allowed[state.role][0]}" aria-label="POS - Supermaket, trang chủ"><span class="pos-wordmark">POS<span class="pos-wordmark-dot"></span></span><span class="pos-brand-caption">BÁN HÀNG TẠI QUẦY</span></a>${groups.map(([group,title])=>{const items=nav.filter(n=>n[3]===group&&allowed[state.role].includes(n[0]));return items.length?`<nav class="navgroup" aria-label="${title}"><div class="navlabel">${title}</div>${items.map(n=>`<a class="navitem ${n[0]===state.page?'active':''}" href="#${n[0]}" title="${n[1]}" ${n[0]===state.page?'aria-current="page"':''}>${icon(n[2])}<span>${n[1]}</span>${n[0]==='promotions'?`<span class="navcount">${promos.filter(p=>promoState(p)==='Đang áp dụng').length}</span>`:''}</a>`).join('')}</nav>`:''}).join('')}<div class="sidebar-bottom"><button class="navitem logout" data-action="logout">${icon('logout')}<span>Đăng xuất</span></button></div></aside><button class="nav-scrim" data-action="close-menu" aria-label="Đóng menu"></button><div class="workspace"><header class="topbar"><div class="row"><button class="iconbtn mobile-menu" data-action="menu" aria-label="Mở menu">${icon('menu')}</button><div class="breadcrumb">${icon('store')}<span>Không gian làm việc</span><span>/</span><span>${page[1]}</span></div></div><div class="topright"><button class="quick-nav" data-action="quick-nav" aria-label="Tìm nhanh chức năng">${icon('search')}<span>Tìm nhanh chức năng</span><kbd>Ctrl K</kbd></button><span class="topdate">${dateFormat(today)} · ${clock}</span><span class="divider"></span><div class="userbox"><span class="avatar">${name.split(' ').slice(-2).map(n=>n[0]).join('')}</span><div><p class="small">${name}</p><select id="role-switch" aria-label="Chọn vai trò để xem demo">${Object.entries(roleNames).map(([r,t])=>`<option value="${r}" ${state.role===r?'selected':''}>${t}</option>`).join('')}</select></div></div></div></header><main class="page ${entering?'page-enter':''}" id="main" tabindex="-1">${({dashboard,products:productPage,promotions:promotionPage,pos,orders:ordersPage,invoices:()=>invoicesPage(false),source:()=>invoicesPage(true),shifts:shiftsPage,reports:reportPage,accounts:accountsPage,permissions:permissionsPage,returns:returnsPage}[state.page]||dashboard)()}</main><footer class="footer"><span>© 2026 POS - Supermaket · Nhóm 06</span><span>Demo giao diện · Dữ liệu mẫu · Chọn vai trò ở góc phải để khám phá</span></footer></div></div>`;
 document.title=`${page[1]} · POS - Supermaket`;bindPage();enhanceSelects();if(entering){animateMetrics();if(state.page==='pos'&&state.role==='cashier')document.getElementById('barcode')?.focus({preventScroll:true})}}
function navigate(page){if(page==='main')return;state.search='';if(!allowed[state.role].includes(page)){toast('Vai trò hiện tại không có quyền vào chức năng này.');return}state.page=page;history.replaceState(null,'','#'+page);render();document.getElementById(state.page==='pos'&&state.role==='cashier'?'barcode':'main')?.focus?.({preventScroll:true});window.scrollTo({top:0,behavior:'instant'})}
function refreshSearch(){const el=document.getElementById('search'),pos=el?.selectionStart;render();const next=document.getElementById('search');next?.focus();if(pos!==null&&pos!==undefined)next?.setSelectionRange(pos,pos)}
function bindPage(){document.getElementById('search')?.addEventListener('input',e=>{state.search=e.target.value;refreshSearch()});document.getElementById('role-switch')?.addEventListener('change',e=>{state.role=e.target.value;state.username=({manager:'quanly.lan',cashier:'thungan.anh',admin:'quantri.nam'})[state.role];navigate(allowed[state.role][0])});
 const filters={'product-status':'productStatus','promo-status':'promoStatus','order-status':'orderStatus','invoice-start':'invoiceStart','invoice-end':'invoiceEnd','shift-status':'shiftStatus','shift-cashier':'shiftCashier','shift-register':'shiftRegister','shift-start':'shiftStart','shift-end':'shiftEnd','account-role':'accountRole'};
 Object.entries(filters).forEach(([id,key])=>document.getElementById(id)?.addEventListener('change',e=>{state[key]=e.target.value;render()}));
 document.getElementById('scan-form')?.addEventListener('submit',e=>{e.preventDefault();const code=document.getElementById('barcode').value.trim(),p=products.find(p=>p.id.toLowerCase()===code.toLowerCase()||p.barcode===code);if(!p)return toast('Không tìm thấy mã sản phẩm. Vui lòng kiểm tra lại.');addProduct(p.id);document.getElementById('barcode')?.focus({preventScroll:true})});
 document.getElementById('report-form')?.addEventListener('submit',e=>{e.preventDefault();state.reportStart=document.getElementById('report-start').value;state.reportEnd=document.getElementById('report-end').value;render()});
 document.getElementById('return-search')?.addEventListener('submit',e=>{e.preventDefault();const id=document.getElementById('return-invoice').value.trim();const inv=myInvoices().find(i=>i.id.toLowerCase()===id.toLowerCase());document.getElementById('return-result').innerHTML=inv?returnResult(inv):`<article class="card">${empty('Không tìm thấy hóa đơn','Kiểm tra mã hóa đơn và phạm vi được phép tra cứu.')}</article>`;bindReturn(inv);enhanceSelects()});
 document.querySelectorAll('[data-quantity]').forEach(el=>el.addEventListener('change',e=>changeQuantity(e.target.dataset.quantity,Number(e.target.value))));}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action],[data-category],[data-add],[data-qty],[data-remove],[data-invoice],[data-edit-product],[data-toggle-product],[data-delete-product],[data-edit-promo],[data-cancel-promo],[data-view-promo],[data-shift],[data-lock-account],[data-cancel-detail]');if(!el||el.disabled)return;
 if(el.dataset.category){state.category=el.dataset.category;render();animateSelection('.chip.active')}
 if(el.dataset.add)addProduct(el.dataset.add);
 if(el.dataset.qty){const row=state.cart.find(i=>i.id===el.dataset.qty);if(row)changeQuantity(row.id,row.qty+Number(el.dataset.delta))}
 if(el.dataset.remove)removeItem(el.dataset.remove);
 if(el.dataset.invoice)showInvoice(el.dataset.invoice);
 if(el.dataset.editProduct)productForm(el.dataset.editProduct);
 if(el.dataset.toggleProduct)toggleProduct(el.dataset.toggleProduct);
 if(el.dataset.deleteProduct)deleteProduct(el.dataset.deleteProduct);
 if(el.dataset.editPromo)promoForm(el.dataset.editPromo);
 if(el.dataset.cancelPromo)cancelPromo(el.dataset.cancelPromo);
 if(el.dataset.viewPromo)viewPromo(el.dataset.viewPromo);
 if(el.dataset.shift)showShift(el.dataset.shift);
 if(el.dataset.lockAccount)lockAccount(Number(el.dataset.lockAccount));
 if(el.dataset.cancelDetail){const order=cancelledOrders.find(o=>o.id===el.dataset.cancelDetail);openModal('Đơn hàng đã hủy',`${note('Đơn chưa thanh toán đã được hủy. Không ghi nhận doanh thu và không trừ tồn kho.')}<div class="kv"><span>Mã đơn</span><span>${order.id}</span></div><div class="kv"><span>Lý do</span><span>${esc(order.reason)}</span></div>`,btn('Đóng','close-modal'))}
 const a=el.dataset.action;if(!a)return;if(a.startsWith('go-'))navigate(a.slice(3));else if(a==='menu'){const open=document.getElementById('sidebar').classList.toggle('open');document.body.classList.toggle('navigation-open',open);el.setAttribute('aria-expanded',String(open));if(open)document.querySelector('#sidebar .navitem.active')?.focus()}else if(a==='close-menu')closeMenu();else if(a==='quick-nav')openQuickNav();else if(a==='logout'){requestLogout()}else if(a==='close-modal')document.getElementById('modal').close();else if(a==='new-product')productForm();else if(a==='new-promo')promoForm();else if(a==='new-account')accountForm();else if(a==='checkout')checkout();else if(a==='cancel-order')cancelOrder();else if(a==='open-shift')openShift();else if(a==='close-shift')closeShift();else if(a==='my-shift'){const s=currentShift();s?showShift(s.id):openShift()}else if(a==='print')window.print();else if(a==='report-today'){state.reportStart=today;state.reportEnd=today;render()}else if(a==='report-week'){state.reportStart='2026-10-29';state.reportEnd=today;render()}else if(a==='source-invoices'){if(state.reportStart>state.reportEnd||!state.reportStart||!state.reportEnd)return toast('Chọn khoảng ngày hợp lệ trước khi đối chiếu.');state.invoiceStart=state.reportStart;state.invoiceEnd=state.reportEnd;navigate('invoices')}else if(a==='login-role'){state.loginRole=el.dataset.role;renderLogin();animateSelection('.roles .active')}
});
window.addEventListener('hashchange',()=>{const dest=location.hash.slice(1);if(!state.loggedIn)return renderLogin();navigate(dest)});
let toastTimeout;function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove('visible'),3800)}
function openModal(title,content,footer='',wide=false){closeOpenSelect(true);const modal=document.getElementById('modal');if(modal.open)modal.close();modal.className=wide?'wide':'';modal.innerHTML=`<div class="modalhead"><h2 id="modal-title">${title}</h2><button class="iconbtn" data-action="close-modal" aria-label="Đóng hộp thoại">${icon('close')}</button></div><div class="modalbody">${content}</div>${footer?`<div class="modalfoot">${footer}</div>`:''}`;enhanceSelects(modal);modal.showModal();modal.querySelector('input:not([disabled]),.select-trigger,textarea:not([disabled])')?.focus({preventScroll:true})}
function requestLogout(){
 closeMenu();const draft=state.cart.length?`Đơn đang lập có ${state.cart.reduce((n,i)=>n+i.qty,0)} sản phẩm sẽ được bỏ khỏi giỏ. `:'';const shift=state.role==='cashier'?currentShift():null;
 confirmBox('Đăng xuất khỏi POS?',draft+'Bạn sẽ trở về màn hình đăng nhập.'+(shift?' Ca '+shift.id+' vẫn đang mở; hãy kết thúc và đối soát ca trước khi bàn giao quầy.':''),'Đăng xuất',()=>{state.loggedIn=false;state.cart=[];history.replaceState(null,'','#login');render()},true);
 const modal=document.getElementById('modal');modal.classList.add('logout-dialog');const stay=modal.querySelector('.modalfoot [data-action="close-modal"]');stay.textContent='Ở lại';stay.focus();
}
function confirmBox(title,text,confirmLabel,callback,danger=false){openModal(title,`<p>${text}</p>`,btn('Quay lại','close-modal')+`<button id="confirm-button" class="btn ${danger?'danger':'primary'}">${confirmLabel}</button>`);document.getElementById('confirm-button').onclick=()=>{callback();document.getElementById('modal').close()}}
function addProduct(id){if(state.role!=='cashier'||!currentShift())return toast('Bạn cần đăng nhập vai trò Thu ngân và mở ca để bán hàng.');const p=products.find(p=>p.id===id);if(!p?.active||p.stock===0)return toast('Sản phẩm ngừng bán hoặc đã hết hàng.');const i=state.cart.find(i=>i.id===id);if(i&&i.qty>=p.stock)return toast('Số lượng không được vượt tồn kho hiện tại.');if(i)i.qty++;else state.cart.push({id,qty:1});checkoutCompleted=false;render();animateAddedProduct(id)}
function changeQuantity(id,qty){const p=products.find(p=>p.id===id);if(qty===0)return removeItem(id);if(!Number.isInteger(qty)||qty<1||qty>p.stock){toast('Số lượng phải là số nguyên từ 1 đến '+p.stock+'.');render();return}state.cart.find(i=>i.id===id).qty=qty;render()}
function removeItem(id){confirmBox('Xóa sản phẩm khỏi đơn?','Sản phẩm sẽ được bỏ khỏi giỏ. Tồn kho chưa thay đổi.','Xóa khỏi đơn',()=>{state.cart=state.cart.filter(i=>i.id!==id);render()})}
function cancelOrder(){if(!state.cart.length)return toast('Giỏ hàng đang trống.');openModal('Hủy đơn chưa thanh toán',`<p>Đơn hàng bị hủy sẽ được lưu trong lịch sử, không ảnh hưởng tồn kho.</p><div class="field" style="margin-top:18px"><label for="cancel-reason">Lý do hủy (không bắt buộc)</label><textarea id="cancel-reason" placeholder="Ví dụ: Khách đổi ý không mua hàng"></textarea></div>`,btn('Giữ đơn','close-modal')+'<button class="btn primary" id="cancel-confirm">Xác nhận hủy đơn</button>');document.getElementById('cancel-confirm').onclick=()=>{cancelledOrders.push({id:'BH-1104-HUY'+(cancelledOrders.length+1),date:today,time:clock,name:cashierName(),reason:document.getElementById('cancel-reason').value.trim()||'Không ghi lý do',total:cartTotals().total});state.cart=[];document.getElementById('modal').close();render();toast('Đã hủy đơn và lưu vào lịch sử demo.')}}
function checkout(){if(state.role!=='cashier'||!currentShift()||!state.cart.length)return toast('Cần ca đang mở và giỏ có sản phẩm.');const t=cartTotals();openModal('Thanh toán đơn hàng',`<div class="checkout-grid"><div><h3 style="margin-bottom:16px">Tóm tắt đơn hàng</h3>${state.cart.map(i=>{const p=products.find(p=>p.id===i.id);return `<div class="kv small"><span>${esc(p.name)} × ${i.qty}</span><span>${money(p.price*i.qty)}</span></div>`}).join('')}<div class="kv"><span>Tạm tính</span><span>${money(t.sub)}</span></div><div class="kv"><span>Giảm khuyến mãi</span><span>−${money(t.discount)}</span></div>${note('Thanh toán tiền mặt theo phạm vi cơ bản của đồ án. Hóa đơn lưu giá và khuyến mãi tại thời điểm bán.','','info')}</div><div><div class="method">${icon('wallet')}Tiền mặt <span style="margin-left:auto">${icon('check')}</span></div><div class="payment-total"><p class="muted small">Tổng tiền cần thu</p><div class="value number">${money(t.total)}</div></div><div class="field"><label for="cash" class="required">Tiền khách đưa</label><input id="cash" type="number" min="0" step="1" placeholder="Nhập số tiền nhận được" inputmode="numeric"><p class="error" id="cash-error" role="alert"></p></div><div class="quickcash">${[Math.ceil(t.total/10000)*10000,Math.ceil(t.total/50000)*50000,Math.ceil(t.total/100000)*100000].filter((v,i,a)=>a.indexOf(v)===i).map(n=>`<button data-cash="${n}">${money(n)}</button>`).join('')}</div><div class="kv"><span>Tiền thừa trả khách</span><span id="change" class="number">—</span></div></div></div>`,btn('Quay lại','close-modal')+'<button class="btn primary" id="pay-confirm" disabled>'+icon('check')+'Xác nhận thanh toán</button>',true);
 const cash=document.getElementById('cash'),pay=document.getElementById('pay-confirm');const validate=()=>{const v=cash.value===''?NaN:Number(cash.value);const valid=Number.isSafeInteger(v)&&v>=t.total&&v>=0;document.getElementById('change').textContent=valid?money(v-t.total):'—';document.getElementById('cash-error').textContent=cash.value&&!valid?'Tiền khách đưa phải là số nguyên và không nhỏ hơn số cần thu.':'';pay.disabled=!valid};cash.oninput=validate;document.querySelectorAll('[data-cash]').forEach(el=>el.onclick=()=>{cash.value=el.dataset.cash;validate()});pay.onclick=()=>{if(checkoutCompleted||!currentShift())return;validate();if(pay.disabled)return;for(const i of state.cart){const p=products.find(p=>p.id===i.id);if(!p.active||i.qty>p.stock)return toast('Sản phẩm không còn đủ tồn hoặc đã ngừng bán.')}checkoutCompleted=true;pay.disabled=true;const s=currentShift(),items=state.cart.map(i=>{const p=products.find(p=>p.id===i.id);return{id:p.id,name:p.name,unit:p.unit,price:p.price,qty:i.qty,percent:discountFor(p.id)}});const inv={id:'HD-20261104-D'+String(invoices.length+1).padStart(3,'0'),order:'BH-1104-D'+(invoices.length+1),date:today,time:clock,name:s.name,register:s.register,shift:s.id,items,sub:t.sub,discount:t.discount,total:t.total,received:Number(cash.value),status:'paid'};state.cart.forEach(i=>{const p=products.find(p=>p.id===i.id);p.stock-=i.qty;p.history=true});invoices.push(inv);state.cart=[];render();showInvoice(inv.id,true);toast('Đã hoàn tất giao dịch minh họa. Không phát sinh thanh toán thật.')};}
function showInvoice(id,success=false){const i=myInvoices().find(i=>i.id===id);if(!i)return toast('Không tìm thấy hóa đơn trong phạm vi được xem.');openModal(success?'Thanh toán thành công':'Chi tiết hóa đơn',`${success?note('Đã lưu hóa đơn và cập nhật tồn trong phiên demo.','success','check'):''}<article class="receipt"><div class="receipt-title"><h2>POS - Supermaket</h2><p class="muted small">Hệ thống bán hàng tại quầy · Nhóm 06</p><h3>HÓA ĐƠN BÁN HÀNG</h3><p class="small muted">${i.id}</p></div><div class="receipt-meta"><div class="kv"><span>Thời gian</span><span>${dateFormat(i.date)} ${i.time}</span></div><div class="kv"><span>Thu ngân / Quầy</span><span>${i.name} · ${i.register}</span></div><div class="kv"><span>Ca làm việc</span><span>${i.shift}</span></div><div class="kv"><span>Phương thức</span><span>Tiền mặt · Đã thanh toán</span></div></div>${table(['Sản phẩm / Giá gốc','SL','Giảm','Thành tiền'],i.items.map(it=>`<tr><td>${esc(it.name)}<span class="muted small" style="display:block">${money(it.price)} / ${esc(it.unit)}</span></td><td>${it.qty}</td><td>${it.percent?it.percent+'%':'—'}</td><td class="align-right number">${money(it.price*it.qty-Math.round(it.price*it.qty*it.percent/100))}</td></tr>`).join(''))}<div class="kv"><span>Tạm tính</span><span>${money(i.sub)}</span></div><div class="kv"><span>Giảm khuyến mãi</span><span>−${money(i.discount)}</span></div><div class="kv total"><span>Tổng thanh toán</span><span class="number">${money(i.total)}</span></div><div class="kv"><span>Tiền khách đưa</span><span>${money(i.received)}</span></div><div class="kv"><span>Tiền thừa</span><span>${money(i.received-i.total)}</span></div><div class="receipt-note"><p>Cảm ơn quý khách. Hẹn gặp lại!</p><div class="barcode" aria-hidden="true"></div><p>Bản minh họa · Không dùng làm hóa đơn thực tế</p></div></article>`,btn('Đóng','close-modal')+btn('In hóa đơn','print','primary','print'))}
function productForm(id){const p=products.find(p=>p.id===id);openModal(p?'Cập nhật sản phẩm':'Thêm sản phẩm mới',`<form id="product-form"><div class="formgrid">${field('p-name','Tên sản phẩm',p?.name||'','text',true,'span2')}${field('p-barcode','Mã vạch',p?.barcode||'','text',true)}<div class="field"><label for="p-category" class="required">Loại hàng</label>${select('p-category',[...new Set(products.map(p=>p.category))].map(c=>[c,c]),p?.category||'Thực phẩm')}</div>${field('p-unit','Đơn vị tính',p?.unit||'','text',true)}${field('p-price','Giá bán (₫)',p?.price??'','number',true)}${field('p-stock','Số lượng hiện có',p?.stock??'','number',true)}<div class="field"><label>Trạng thái sau lưu</label><span class="badge ${p?.active===false?'neutral':'success'}">${p?.active===false?'Ngừng bán':'Đang bán'}</span></div></div><p id="form-error" class="error" role="alert"></p><div class="formactions">${btn('Hủy','close-modal')}<button type="submit" class="btn primary">${icon('check')}Lưu sản phẩm</button></div></form>${p?note('Cập nhật giá không làm thay đổi hóa đơn cũ. Dữ liệu đã bán được giữ nguyên theo thời điểm phát hành.'):''}`);document.getElementById('product-form').onsubmit=e=>{e.preventDefault();const name=value('p-name'),barcode=value('p-barcode'),unit=value('p-unit'),price=Number(value('p-price')),stock=Number(value('p-stock'));const err=(!name||!barcode||!unit)?'Nhập đầy đủ các trường bắt buộc.':products.some(x=>x.id!==id&&x.barcode===barcode)?'Mã vạch đã tồn tại. Vui lòng dùng mã khác.':(!Number.isSafeInteger(price)||price<0||!Number.isSafeInteger(stock)||stock<0)?'Giá và tồn kho phải là số nguyên không âm.':'';if(err)return formError(err);const data={name,barcode,unit,price,stock,category:value('p-category')};if(p)Object.assign(p,data);else products.push({...data,id:'SP'+String(Math.max(...products.map(p=>Number(p.id.slice(2))))+1).padStart(3,'0'),active:true,kind:'box',color:'#a7bdd5',history:false});document.getElementById('modal').close();render();toast('Đã lưu sản phẩm trong phiên demo.')};}
const value=id=>document.getElementById(id).value.trim();
const formError=text=>document.getElementById('form-error').textContent=text;
const field=(id,label,v='',type='text',required=false,extra='')=>`<div class="field ${extra}"><label for="${id}" ${required?'class="required"':''}>${label}</label><input id="${id}" type="${type}" value="${esc(v)}" ${required?'required':''} ${type==='number'?'min="0" step="1"':''} autocomplete="off"></div>`;
function toggleProduct(id){const p=products.find(p=>p.id===id);confirmBox(p.active?'Ngừng bán sản phẩm?':'Kích hoạt lại sản phẩm?',`${esc(p.name)}. ${p.active?'Sản phẩm sẽ không được thêm mới vào giỏ. Dữ liệu hóa đơn cũ được giữ nguyên.':'Sản phẩm sẽ xuất hiện trong danh sách có thể bán.'}`,p.active?'Xác nhận ngừng bán':'Kích hoạt',()=>{p.active=!p.active;render();toast('Đã cập nhật trạng thái sản phẩm.')})}
function deleteProduct(id){const p=products.find(p=>p.id===id);if(p.active)return toast('Chỉ xóa được sản phẩm đã ngừng bán.');if(p.history||invoices.some(i=>i.items.some(it=>it.id===id)))return openModal('Không thể xóa sản phẩm',note('Sản phẩm có lịch sử giao dịch. Hãy giữ trạng thái Ngừng bán để bảo toàn hóa đơn.','warning'),btn('Đã hiểu','close-modal'));confirmBox('Xóa sản phẩm đã ngừng bán?',`${esc(p.name)} chưa phát sinh giao dịch. Thao tác xóa không thể hoàn tác trong phiên demo.`, 'Xóa sản phẩm',()=>{products.splice(products.indexOf(p),1);render();toast('Đã xóa sản phẩm chưa có lịch sử.')},true)}
function promoForm(id){const p=promos.find(p=>p.id===id);if(p&&promoState(p)!=='Sắp diễn ra')return viewPromo(id);openModal(p?'Chỉnh sửa khuyến mãi':'Tạo chương trình khuyến mãi',`<form id="promo-form"><div class="formgrid"><div class="field span2"><label for="promo-product" class="required">Sản phẩm áp dụng</label>${select('promo-product',products.filter(p=>p.active).map(p=>[p.id,p.id+' · '+p.name]),p?.product||products[0].id)}</div>${field('promo-percent','Phần trăm giảm (%)',p?.percent??'','number',true)}<div></div>${field('promo-start','Ngày bắt đầu',p?.start||today,'date',true)}${field('promo-end','Ngày kết thúc',p?.end||'','date',true)}</div><p class="error" id="form-error" role="alert"></p><div class="formactions">${btn('Hủy','close-modal')}<button class="btn primary" type="submit">Lưu khuyến mãi</button></div></form>${note('Mức giảm lớn hơn 0 và không quá 100%. Ngày kết thúc phải sau ngày bắt đầu. Không trùng thời gian trên cùng sản phẩm.')}`);document.getElementById('promo-form').onsubmit=e=>{e.preventDefault();const product=value('promo-product'),percent=Number(value('promo-percent')),start=value('promo-start'),end=value('promo-end');if(percent<=0||percent>100)return formError('Phần trăm giảm phải trong khoảng (0, 100].');if(!start||!end||end<=start)return formError('Ngày kết thúc phải sau ngày bắt đầu.');if(promos.some(x=>x.id!==id&&!x.cancelled&&x.product===product&&start<=x.end&&end>=x.start))return formError('Sản phẩm đã có khuyến mãi trùng khoảng thời gian.');if(p)Object.assign(p,{product,percent,start,end});else promos.push({id:'KM'+String(promos.length+1).padStart(3,'0'),product,percent,start,end,cancelled:false});document.getElementById('modal').close();render();toast('Đã lưu chương trình trong phiên demo.')};}
function cancelPromo(id){const p=promos.find(p=>p.id===id);if(!['Đang áp dụng','Sắp diễn ra'].includes(promoState(p)))return;confirmBox('Hủy chương trình khuyến mãi?','Giao dịch mới sẽ không được áp dụng chương trình này. Hóa đơn đã phát hành giữ nguyên mức giảm.','Xác nhận hủy',()=>{p.cancelled=true;render();toast('Đã hủy khuyến mãi cho các giao dịch mới.')})}
function viewPromo(id){const p=promos.find(p=>p.id===id),prod=products.find(x=>x.id===p.product);openModal('Chi tiết chương trình',`<div class="kv"><span>Sản phẩm</span><span>${esc(prod?.name||p.product)}</span></div><div class="kv"><span>Mức giảm</span><span>${p.percent}%</span></div><div class="kv"><span>Hiệu lực</span><span>${dateFormat(p.start)} – ${dateFormat(p.end)}</span></div><div class="kv"><span>Trạng thái</span>${badge(promoState(p),'neutral')}</div>${note('Chương trình đã kết thúc hoặc bị hủy chỉ được xem; không sửa lại lịch sử hóa đơn.')}`,btn('Đóng','close-modal'))}
function openShift(){if(state.role!=='cashier')return toast('Chỉ Thu ngân mở ca của mình.');if(currentShift())return toast('Bạn đã có một ca đang mở.');openModal('Mở ca bán hàng',`<form id="shift-open-form"><div class="field"><label>Thu ngân</label><input value="${esc(cashierName())}" disabled></div><div class="formgrid" style="margin-top:16px"><div class="field"><label for="register" class="required">Quầy bán hàng</label>${select('register',[['Quầy 01','Quầy 01'],['Quầy 03','Quầy 03']], 'Quầy 01')}</div>${field('opening','Tiền đầu ca (₫)','','number',true)}</div><p class="error" id="form-error" role="alert"></p><div class="formactions">${btn('Hủy','close-modal')}<button type="submit" class="btn primary">Xác nhận mở ca</button></div></form>${note('Tiền đầu ca có thể bằng 0. Mỗi thu ngân chỉ có một ca đang mở.')}`);document.getElementById('shift-open-form').onsubmit=e=>{e.preventDefault();if(currentShift())return formError('Bạn đã có ca đang mở.');const opening=Number(value('opening'));if(!Number.isSafeInteger(opening)||opening<0)return formError('Tiền đầu ca phải là số nguyên không âm.');shifts.push({id:'CA-0411-D'+(shifts.length+1),date:today,name:cashierName(),register:value('register'),start:clock,end:null,opening,actual:null,status:'open'});document.getElementById('modal').close();render();toast('Đã mở ca mới trong phiên demo.')};}
function closeShift(){const s=currentShift();if(state.role!=='cashier'||!s)return toast('Không có ca đang mở của bạn.');if(state.cart.length)return toast('Hãy thanh toán hoặc hủy đơn đang lập trước khi đóng ca.');const rows=invoices.filter(i=>i.shift===s.id),revenue=sum(rows),expected=s.opening+revenue;openModal('Kết thúc & đối soát ca',`<p class="muted small" style="margin-bottom:18px">${s.id} · ${s.register} · Mở lúc ${s.start}</p><div class="kv"><span>Tiền đầu ca</span><span>${money(s.opening)}</span></div><div class="kv"><span>Doanh thu tiền mặt</span><span>${money(revenue)}</span></div><div class="kv total"><span>Tiền dự kiến trong két</span><span>${money(expected)}</span></div><form id="close-shift-form"><div class="field" style="margin-top:20px"><label for="actual" class="required">Tiền thực tế kiểm đếm (₫)</label><input id="actual" type="number" required min="0" step="1" placeholder="Nhập số tiền đang có trong két"></div><div class="kv"><span>Chênh lệch (thực tế − dự kiến)</span><span id="difference">—</span></div><p class="error" id="form-error" role="alert"></p><div class="formactions">${btn('Quay lại','close-modal')}<button class="btn primary" type="submit">Xem lại & xác nhận</button></div></form>${note('Ca đã kết thúc sẽ bị khóa và không nhận hóa đơn mới.','warning','lock')}`);document.getElementById('actual').oninput=e=>{const n=Number(e.target.value);document.getElementById('difference').textContent=e.target.value&&Number.isSafeInteger(n)&&n>=0?money(n-expected):'—'};document.getElementById('close-shift-form').onsubmit=e=>{e.preventDefault();const actual=Number(value('actual'));if(!Number.isSafeInteger(actual)||actual<0)return formError('Tiền thực tế phải là số nguyên không âm.');confirmBox('Xác nhận kết thúc ca?',`Tiền dự kiến: ${money(expected)}. Tiền thực tế: ${money(actual)}. Chênh lệch: ${money(actual-expected)}. Sau xác nhận, ca không thể nhận giao dịch mới.`, 'Kết thúc ca',()=>{if(s.status!=='open')return;s.status='closed';s.actual=actual;s.end=clock;render();toast('Đã chốt ca. Mở ca mới trước khi tiếp tục bán hàng.')})};}
function showShift(id){const s=shifts.find(s=>s.id===id);if(!s||(state.role==='cashier'&&s.name!==cashierName()))return toast('Bạn không có quyền xem ca này.');const rows=invoices.filter(i=>i.shift===id),revenue=sum(rows),expected=s.opening+revenue;openModal('Chi tiết ca làm việc',`<div class="between" style="margin-bottom:16px"><div><h3>${s.id}</h3><p class="muted small">${s.name} · ${s.register}</p></div>${badge(s.status==='open'?'Đang mở':'Đã kết thúc',s.status==='open'?'success':'neutral')}</div><div class="formgrid"><div class="kv"><span>Giờ mở</span><span>${dateFormat(s.date)} ${s.start}</span></div><div class="kv"><span>Giờ kết thúc</span><span>${s.end||'Chưa kết thúc'}</span></div><div class="kv"><span>Tiền đầu ca</span><span>${money(s.opening)}</span></div><div class="kv"><span>Doanh thu tiền mặt</span><span>${money(revenue)}</span></div><div class="kv"><span>Tiền dự kiến</span><span>${money(expected)}</span></div><div class="kv"><span>Tiền thực tế</span><span>${s.actual===null?'Chưa đối soát':money(s.actual)}</span></div></div>${s.actual!==null?`<div class="kv total"><span>Chênh lệch</span><span>${money(s.actual-expected)}</span></div>`:''}<h3 style="margin:20px 0 15px">Hóa đơn thuộc ca (${rows.length})</h3>${table(['Mã hóa đơn','Thời gian','Tổng thanh toán'],rows.map(i=>`<tr><td><button class="cell-link" data-invoice="${i.id}">${i.id}</button></td><td>${i.time}</td><td class="align-right">${money(i.total)}</td></tr>`).join(''))}`,btn('Đóng','close-modal'),true)}
function accountForm(){openModal('Tạo tài khoản mới',`<form id="account-form"><div class="formgrid">${field('a-name','Họ và tên','','text',true,'span2')}${field('a-username','Tên đăng nhập','','text',true)}${field('a-password','Mật khẩu minh họa','','password',true)}<div class="field span2"><label for="a-role" class="required">Vai trò</label>${select('a-role',Object.entries(roleNames),'cashier')}</div></div><p class="error" id="form-error" role="alert"></p><div class="formactions">${btn('Hủy','close-modal')}<button class="btn primary" type="submit">Tạo tài khoản</button></div></form>${note('Chỉ nhập thông tin giả khi thử demo. Mật khẩu không được lưu hoặc gửi đi.')}`);document.getElementById('account-form').onsubmit=e=>{e.preventDefault();const username=value('a-username');if(accounts.some(a=>a.username.toLowerCase()===username.toLowerCase()))return formError('Tên đăng nhập đã tồn tại.');accounts.push({id:Math.max(...accounts.map(a=>a.id))+1,name:value('a-name'),username,role:value('a-role'),active:true});document.getElementById('modal').close();render();toast('Đã tạo tài khoản minh họa. Không tạo tài khoản thật.')};}
function lockAccount(id){const a=accounts.find(a=>a.id===id);if(state.role!=='admin'||!a?.active||a.username===state.username)return;confirmBox('Khóa tài khoản nhân viên?',`Tài khoản ${esc(a.username)} sẽ không thể đăng nhập. Dữ liệu giao dịch và ca cũ vẫn được giữ lại.`, 'Xác nhận khóa',()=>{a.active=false;render();toast('Đã khóa tài khoản trong phiên demo.')})}
function returnResult(i){return `<article class="card"><div class="cardhead"><div><h2>2. Chọn hàng cần trả / đổi</h2><p>${i.id} · ${dateFormat(i.date)} · ${i.register}</p></div>${badge('Đã thanh toán','success')}</div><form id="return-form" data-invoice-id="${i.id}">${i.items.map((it,j)=>`<div class="cart-line"><div class="info"><p class="name">${esc(it.name)}</p><p class="muted small">Đã mua ${it.qty} ${it.unit.toLowerCase()} · Giá sau giảm ${money(it.price*(1-it.percent/100))}</p></div><div class="field" style="width:80px"><label for="return-qty-${j}">SL trả</label><input type="number" min="0" max="${it.qty}" step="1" id="return-qty-${j}" value="0" data-return-qty="${j}"></div></div>`).join('')}<div class="field" style="margin-top:18px"><label for="replacement">Hàng đổi mới (tùy chọn)</label>${select('replacement',[['','Không đổi, chỉ trả hàng'],...products.filter(p=>p.active&&p.stock>0).map(p=>[p.id,p.name+' · '+money(p.price*(1-discountFor(p.id)/100))])],'')}</div><div class="field" style="margin-top:15px"><label for="return-reason" class="required">Lý do xử lý</label><textarea id="return-reason" required placeholder="Nhập lý do trả hoặc đổi hàng"></textarea></div><div class="kv total"><span>Chênh lệch</span><span id="return-total">0 ₫</span></div><p class="muted small">Đổi mới minh họa 1 sản phẩm. Số tiền dùng giá đã lưu trên hóa đơn gốc.</p><p class="error" id="form-error" role="alert"></p><div class="formactions"><button class="btn primary" type="submit">${state.role==='manager'?'Xem xét đề nghị':'Gửi quản lý xác nhận'}</button></div></form></article>`}
function bindReturn(i){if(!i)return;const calc=()=>{let total=0,qtyTotal=0;for(let j=0;j<i.items.length;j++){const it=i.items[j],qty=Number(value('return-qty-'+j));if(!Number.isInteger(qty)||qty<0||qty>it.qty)return {error:'Số lượng trả phải từ 0 đến số lượng đã mua.'};qtyTotal+=qty;total+=Math.round(it.price*qty*(1-it.percent/100))}const replacement=products.find(p=>p.id===value('replacement'));if(replacement)total-=replacement.price-Math.round(replacement.price*discountFor(replacement.id)/100);document.getElementById('return-total').textContent=(total<0?'Thu thêm ':'Hoàn lại ')+money(Math.abs(total));return{total,qtyTotal}};document.querySelectorAll('[data-return-qty]').forEach(el=>el.oninput=calc);document.getElementById('replacement').onchange=calc;document.getElementById('return-form').onsubmit=e=>{e.preventDefault();const result=calc();if(result.error)return formError(result.error);if(!result.qtyTotal)return formError('Chọn ít nhất một sản phẩm cần trả.');openModal('Đề nghị trả / đổi hàng',`${note('Đề nghị cần Quản lý ca xác nhận trước khi hoàn tiền hoặc thay đổi tồn kho.','warning')}<div class="kv"><span>Hóa đơn gốc</span><span>${i.id}</span></div><div class="kv"><span>${result.total<0?'Cần thu thêm':'Cần hoàn lại'}</span><span>${money(Math.abs(result.total))}</span></div><p class="small muted" style="margin-top:15px">Đây là trạng thái minh họa chờ duyệt. Hóa đơn gốc, tồn kho và báo cáo chưa thay đổi.</p>`,btn('Đóng','close-modal')+(state.role==='manager'?'<button class="btn primary" id="approve-return">Xác nhận duyệt minh họa</button>':''));document.getElementById('approve-return')?.addEventListener('click',()=>{document.getElementById('modal').close();toast('Đã xem trạng thái duyệt minh họa. Chưa ghi hoàn tiền hoặc điều chỉnh dữ liệu.')})};}
function renderLogin(){closeOpenSelect(true);lastRenderKey='';document.body?.classList.remove('navigation-open');document.getElementById('root').innerHTML=`<div class="login-layout"><section class="login-hero"><div class="brand pos-brand"><span class="pos-wordmark">POS<span class="pos-wordmark-dot"></span></span><span class="pos-brand-caption">BÁN HÀNG TẠI QUẦY</span></div><div><div class="eyebrow">MỖI GIAO DỊCH, MỘT TRẢI NGHIỆM TỐT</div><h1>Bán hàng gọn gàng.<br>Quản lý nhẹ nhàng.</h1><p>Không gian làm việc chung cho thu ngân, quản lý và người quản trị siêu thị.</p><div class="login-visual"><div class="between"><h3>Vận hành trong tầm tay</h3>${badge('Sẵn sàng','success')}</div><div class="login-chart">${[43,65,52,95,70,84,76].map(h=>`<i style="--h:${h}%"></i>`).join('')}</div><div class="between small muted" style="margin-top:18px"><span>Bán hàng</span><span>Ca làm việc</span><span>Báo cáo</span></div></div></div><p class="small">Đồ án Phát triển phần mềm chuyên nghiệp · Nhóm 06</p></section><section class="login-form"><div><span class="badge">Bản demo giao diện</span><h2>Chào mừng trở lại</h2><p class="muted small">Đăng nhập để bắt đầu không gian làm việc của bạn.</p><form id="login-form"><div class="field"><label for="username" class="required">Tên đăng nhập</label><input id="username" autocomplete="off" required value="${state.loginRole==='cashier'?'thungan.anh':state.loginRole==='manager'?'quanly.lan':'quantri.nam'}"></div><div class="field"><label for="password" class="required">Mật khẩu demo</label><input id="password" type="password" autocomplete="off" value="demo123" required></div><p class="error" id="login-error" role="alert"></p><button class="btn primary full" type="submit">Vào không gian làm việc ${icon('arrow')}</button></form><p class="small muted" style="margin-top:24px">Chọn vai trò để trải nghiệm</p><div class="roles">${Object.entries(roleNames).map(([r,t])=>`<button class="${state.loginRole===r?'active':''}" data-action="login-role" data-role="${r}">${t}</button>`).join('')}</div><p class="muted small" style="margin-top:16px">Mật khẩu mẫu: demo123. Chỉ dùng dữ liệu giả; demo không xác thực qua máy chủ.</p></div></section></div>`;document.getElementById('login-form').onsubmit=e=>{e.preventDefault();const a=accounts.find(a=>a.username===value('username'));if(!a||value('password')!=='demo123')return document.getElementById('login-error').textContent='Tên đăng nhập hoặc mật khẩu không đúng.';if(!a.active)return document.getElementById('login-error').textContent='Tài khoản đã bị khóa. Vui lòng liên hệ quản trị.';state.role=a.role;state.username=a.username;state.loggedIn=true;navigate(allowed[a.role][0])};}

// Motion only runs on a new screen; cart edits and typing never replay page animation.
const reducedMotion=()=>Boolean(window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches);
function animateMetrics(){
 if(reducedMotion())return;
 document.querySelectorAll('[data-count]').forEach((el,index)=>el.animate?.([{opacity:.4,transform:'translateY(3px)'},{opacity:1,transform:'translateY(0)'}],{duration:380,delay:index*35,easing:'cubic-bezier(.22,1,.36,1)'}));
}

function animateAddedProduct(id){
 if(reducedMotion())return;
 document.querySelector?.('[data-add="'+id+'"]')?.animate?.([{borderColor:'#2563eb',background:'#eff6ff'},{borderColor:'#dce6f3',background:'#fff'}],{duration:480,easing:'ease-out'});
 document.querySelector?.('[data-cart-line="'+id+'"]')?.animate?.([{opacity:.5,transform:'translateX(12px)'},{opacity:1,transform:'translateX(0)'}],{duration:260,easing:'cubic-bezier(.2,.8,.2,1)'});
 document.querySelector?.('.cart-summary .total')?.animate?.([{background:'#eaf2ff'},{background:'transparent'}],{duration:550});
}
function closeMenu(){const wasOpen=document.body?.classList.contains('navigation-open');document.getElementById('sidebar')?.classList.remove('open');document.body?.classList.remove('navigation-open');const trigger=document.querySelector?.('[data-action="menu"]');trigger?.setAttribute('aria-expanded','false');if(wasOpen)trigger?.focus()}

function openQuickNav(){
 if(!state.loggedIn)return;const existing=document.getElementById('modal');if(existing.open&&!existing.classList.contains('command-dialog'))return;
 const items=nav.filter(n=>allowed[state.role].includes(n[0]));
 const list=query=>items.filter(n=>matches(n[1],query)).map(n=>`<button class="command-item" data-jump="${n[0]}"><span class="command-icon">${icon(n[2])}</span><span>${n[1]}<small>${n[0]===state.page?'Màn hình hiện tại':'Đi tới chức năng'}</small></span>${icon('chevron')}</button>`).join('')||`<div class="command-empty">${icon('search')}<p>Không tìm thấy chức năng phù hợp.</p></div>`;
 openModal('Đi tới chức năng',`<div class="command-search">${icon('search')}<input id="command-search" type="search" autocomplete="off" aria-label="Tìm chức năng" placeholder="Tìm tên màn hình…"><kbd>Esc</kbd></div><div class="command-results" id="command-results">${list('')}</div><div class="command-hint"><span>Chỉ hiển thị chức năng thuộc vai trò của bạn</span><span>↓ Chọn · Enter Mở</span></div>`);
 document.getElementById('modal').classList.add('command-dialog');
 const input=document.getElementById('command-search');input.focus();input.oninput=()=>document.getElementById('command-results').innerHTML=list(input.value);
 input.onkeydown=e=>{if(e.key==='ArrowDown'){e.preventDefault();document.querySelector('.command-item')?.focus()}};
 document.getElementById('command-results').onkeydown=e=>{const nodes=[...document.querySelectorAll('.command-item')],at=nodes.indexOf(document.activeElement);if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();const next=at+(e.key==='ArrowDown'?1:-1);if(next<0)input.focus();else nodes[Math.min(nodes.length-1,next)]?.focus()}};
}
 document.addEventListener('click',e=>{const target=e.target.closest('[data-jump]');if(target){document.getElementById('modal').close();navigate(target.dataset.jump)}});
 document.addEventListener('keydown',e=>{if(state.loggedIn&&state.role==='cashier'&&state.page==='pos'&&!document.getElementById('modal').open){if(e.key==='F2'){e.preventDefault();document.getElementById('barcode')?.focus()}if(e.key==='F4'){e.preventDefault();checkout()}}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&state.loggedIn){e.preventDefault();openQuickNav()}if(e.key==='Escape')closeMenu();if(e.key==='Tab'&&document.body.classList.contains('navigation-open')){const nodes=[...document.querySelectorAll('#sidebar a,#sidebar button:not([disabled])')].filter(n=>n.getClientRects().length),first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});


// Progressively enhanced selects keep the original form values/change handlers.
// The visible trigger/listbox are fully custom; the native popup never opens.
let activeSelect=null;
function closeOpenSelect(immediate=false){activeSelect?.close(immediate,false)}
function animateSelection(selector){if(reducedMotion())return;document.querySelector?.(selector)?.animate?.([{transform:'scale(.97)'},{transform:'scale(1)'}],{duration:190,easing:'cubic-bezier(.22,1,.36,1)'})}
function enhanceSelects(scope=document){
 scope.querySelectorAll('select:not([data-enhanced])').forEach(native=>{
  native.dataset.enhanced='true';
  const id=native.id||'select-'+Math.random().toString(36).slice(2),role=id==='role-switch';
  const labels=[...(native.labels||[])],label=native.getAttribute('aria-label')||labels.map(l=>l.textContent.trim()).join(' ')||'Chọn một mục';
  const wrap=document.createElement('div');wrap.className='custom-select'+(role?' role-select':'');native.before(wrap);wrap.append(native);native.hidden=true;
  const trigger=document.createElement('button');trigger.type='button';trigger.id=id+'--trigger';trigger.className='select-trigger';trigger.setAttribute('role','combobox');trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');trigger.setAttribute('aria-label',label);trigger.setAttribute('aria-controls',id+'--list');trigger.disabled=native.disabled;
  if(native.required||labels.some(l=>l.classList.contains('required')))trigger.setAttribute('aria-required','true');labels.forEach(l=>l.htmlFor=trigger.id);wrap.append(trigger);
  const menu=document.createElement('div');menu.className='select-menu'+(role?' role-menu':'');menu.setAttribute('popover','manual');wrap.append(menu);
  const details={cashier:['pos','Bán hàng và ca tại quầy'],manager:['chart','Sản phẩm, doanh thu và vận hành'],admin:['shield','Tài khoản và phân quyền']};
  let expanded=false,timer,highlight=-1;
  const refresh=()=>{trigger.innerHTML=`<span class="select-value">${esc(native.selectedOptions[0]?.textContent||'Chọn…')}</span><span class="select-chevron">${icon('chevron')}</span>`;trigger.disabled=native.disabled};refresh();
  native.addEventListener('change',refresh);
  const options=()=>[...menu.querySelectorAll('[role="option"]:not([disabled])')];
  const mark=index=>{const nodes=options();if(!nodes.length)return;highlight=Math.max(0,Math.min(nodes.length-1,index));nodes.forEach((n,i)=>n.dataset.highlighted=String(i===highlight));nodes[highlight].focus({preventScroll:true});nodes[highlight].scrollIntoView({block:'nearest'})};
  const draw=query=>{const nodes=[...native.options].filter(o=>matches(o.textContent,query));menu.querySelector('.select-options').innerHTML=nodes.map(o=>{const checked=o.value===native.value,detail=role?details[o.value]:null;return `<button type="button" role="option" aria-selected="${checked}" class="select-option ${checked?'is-selected':''}" data-value="${esc(o.value)}" tabindex="-1" ${o.disabled?'disabled':''}>${detail?`<span class="select-option-icon">${icon(detail[0])}</span>`:''}<span class="select-option-text">${esc(o.textContent)}${detail?`<small>${detail[1]}</small>`:''}</span><span class="select-tick">${checked?icon('check'):''}</span></button>`}).join('')||'<div class="select-no-results">Không có lựa chọn phù hợp.</div>';highlight=-1};
  const reposition=()=>{if(!expanded||!trigger.isConnected)return;const rect=trigger.getBoundingClientRect(),gutter=12,width=Math.min(Math.max(rect.width,role?265:205),innerWidth-gutter*2),below=innerHeight-rect.bottom-8,above=rect.top-8,up=below<190&&above>below;menu.style.width=width+'px';menu.style.maxHeight=Math.max(150,innerHeight-24)+'px';menu.dataset.direction=up?'up':'down';const list=menu.querySelector('.select-options');list.style.maxHeight=Math.max(96,Math.min(280,(up?above:below)-(menu.querySelector('.select-menu-search')?62:role?55:16)))+'px';const height=menu.getBoundingClientRect().height;menu.style.left=Math.max(gutter,Math.min(rect.left,innerWidth-width-gutter))+'px';menu.style.top=Math.max(gutter,Math.min(up?rect.top-height-7:rect.bottom+7,innerHeight-height-gutter))+'px';menu.style.transformOrigin=up?'bottom center':'top center'};

  const close=(immediate=false,restore=true)=>{if(!expanded)return;expanded=false;trigger.setAttribute('aria-expanded','false');menu.style.pointerEvents='none';if(activeSelect?.native===native)activeSelect=null;const hide=()=>{if(!menu.isConnected)return;if(menu.hidePopover){if(menu.matches(':popover-open'))menu.hidePopover()}else menu.hidden=true;menu.classList.remove('is-closing')};clearTimeout(timer);if(!immediate&&!reducedMotion()&&menu.animate){menu.animate([{opacity:1,transform:'translateY(0) scale(1)'},{opacity:0,transform:`translateY(${menu.dataset.direction==='up'?3:-3}px) scale(.98)`}],{duration:130,easing:'ease-in',fill:'forwards'});timer=setTimeout(hide,130)}else hide();if(restore&&trigger.isConnected)trigger.focus({preventScroll:true})};
  const open=(keyboard=false,last=false)=>{if(native.disabled)return;if(expanded){close();return}closeOpenSelect(true);clearTimeout(timer);menu.getAnimations?.().forEach(a=>a.cancel());menu.style.pointerEvents='auto';menu.classList.remove('is-closing');menu.innerHTML=(role?'<div class="select-menu-heading">Chọn không gian làm việc</div>':native.options.length>6?`<div class="select-menu-search">${icon('search')}<input type="search" aria-label="Tìm trong ${esc(label)}" placeholder="Tìm lựa chọn…" autocomplete="off"></div>`:'')+`<div class="select-options" role="listbox" id="${id}--list" aria-label="${esc(label)}"></div>`;draw('');expanded=true;trigger.setAttribute('aria-expanded','true');if(menu.showPopover)menu.showPopover();else menu.hidden=false;activeSelect={native,close,reposition};reposition();if(!reducedMotion())menu.animate?.([{opacity:0,transform:`translateY(${menu.dataset.direction==='up'?4:-4}px) scale(.975)`},{opacity:1,transform:'translateY(0) scale(1)'}],{duration:190,easing:'cubic-bezier(.2,.8,.2,1)'});const search=menu.querySelector('input');if(search){search.oninput=()=>{draw(search.value);reposition()};search.onkeydown=e=>{if(e.key==='ArrowDown'){e.preventDefault();mark(0)}}}if(keyboard){const selected=options().findIndex(n=>n.getAttribute('aria-selected')==='true');mark(last?options().length-1:Math.max(0,selected))}else search?.focus({preventScroll:true})};
  wrap.addEventListener('focusout',()=>queueMicrotask(()=>{if(expanded&&!wrap.contains(document.activeElement))close(true,false)}));
  trigger.onclick=()=>open();
  trigger.onkeydown=e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(expanded)mark(e.key==='ArrowUp'?options().length-1:Math.max(0,options().findIndex(n=>n.getAttribute('aria-selected')==='true')));else open(true,e.key==='ArrowUp')}else if(e.key==='Enter'||e.key===' '){e.preventDefault();if(expanded)close();else open(true)}else if(e.key==='Escape'){if(expanded){e.preventDefault();e.stopPropagation();close()}}else if(e.key.length===1&&!e.ctrlKey&&!e.metaKey){if(!expanded)open();const search=menu.querySelector('input');if(search){search.value=e.key;draw(e.key);search.focus()}else{const index=options().findIndex(n=>matches(n.textContent.trim().slice(0,e.key.length),e.key));if(index>=0)mark(index)}}};

  menu.onclick=e=>{const option=e.target.closest('[role="option"]');if(!option||option.disabled)return;const next=option.dataset.value,changed=next!==native.value;close(true,false);native.value=next;refresh();if(changed)native.dispatchEvent(new Event('change',{bubbles:true}));document.getElementById(trigger.id)?.focus({preventScroll:true})};
  menu.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close()}else if(e.key==='Tab'){close(true,true)}else if(e.target.tagName!=='INPUT'&&['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();mark(e.key==='Home'?0:e.key==='End'?options().length-1:highlight+(e.key==='ArrowDown'?1:-1))}};
  menu.hidden=!menu.showPopover;
 });
}
document.addEventListener('pointerdown',e=>{if(activeSelect&&!e.target.closest('.custom-select'))closeOpenSelect()});
window.addEventListener('resize',()=>activeSelect?.reposition());
window.addEventListener('scroll',()=>activeSelect?.reposition(),true);

if(location.hash==='#login')state.loggedIn=false;else if(location.hash.slice(1))state.page=location.hash.slice(1);
render();
